import React from 'react';
import './NestedArchitectureRenderer.css';

/**
 * NestedArchitectureRenderer - A component designed to properly render the hierarchical
 * structure of deployment units and their contained objects (folders and nested units)
 */
const NestedArchitectureRenderer = ({ architectureData }) => {
  
  // Filter root-level deployment units (those without a parent)
  const getRootUnits = (units) => {
    return units.filter(unit => !unit.parentId);
  };

  // Get child units for a specific parent
  const getChildUnits = (units, parentId) => {
    return units.filter(unit => 
      unit.parentId === parentId && unit.parentType === 'DEPLOYMENT_UNIT'
    );
  };

  // Get units contained in a specific folder
  const getUnitsInFolder = (units, folderId) => {
    return units.filter(unit => 
      unit.parentId === folderId && unit.parentType === 'FOLDER'
    );
  };

  // Render a deployment unit with all its nested content
  const renderDeploymentUnit = (unit, level = 0, units) => {
    const childUnits = getChildUnits(units, unit.id);
    
    return (
      <div key={unit.id} className={`deployment-unit level-${level}`}>
        <div className="unit-header">
          <div className="unit-info">
            <span className="unit-name">{unit.name}</span>
            <span className="unit-type">{unit.type}</span>
            {unit.uuaa && <span className="unit-uuaa">UUAA: {unit.uuaa}</span>}
            {unit.code && <span className="unit-code">Code: {unit.code}</span>}
          </div>
          {unit.description && (
            <div className="unit-description">{unit.description}</div>
          )}
          {unit.className && (
            <div className="unit-class">Class: {unit.className}</div>
          )}
        </div>
        
        <div className="unit-content">
          {/* Render Component Folders */}
          {unit.componentFolders && unit.componentFolders.length > 0 && (
            <div className="folders-section">
              <div className="section-title">Folders</div>
              <div className="folders-container">
                {unit.componentFolders.map(folder => 
                  renderComponentFolder(folder, units)
                )}
              </div>
            </div>
          )}
          
          {/* Render Child Deployment Units */}
          {childUnits.length > 0 && (
            <div className="children-section">
              <div className="section-title">Child Units</div>
              <div className="children-container">
                {childUnits.map(childUnit => 
                  renderDeploymentUnit(childUnit, level + 1, units)
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    );
  };

  // Render a component folder with its contained units
  const renderComponentFolder = (folder, units) => {
    const containedUnits = getUnitsInFolder(units, folder.id);
    
    return (
      <div key={folder.id} className={`component-folder folder-${folder.type.toLowerCase()}`}>
        <div className="folder-header">
          <span className="folder-type">{folder.type}</span>
          <span className="folder-count">({containedUnits.length} items)</span>
        </div>
        
        {folder.description && (
          <div className="folder-description">{folder.description}</div>
        )}
        
        <div className="folder-content">
          {containedUnits.length > 0 ? (
            <div className="contained-units">
              {containedUnits.map(unit => renderContainedUnit(unit))}
            </div>
          ) : (
            <div className="empty-folder">No items</div>
          )}
        </div>
      </div>
    );
  };

  // Render a unit that's contained within a folder
  const renderContainedUnit = (unit) => {
    return (
      <div key={unit.id} className={`contained-unit unit-type-${unit.type.toLowerCase()}`}>
        <div className="contained-unit-header">
          <span className="contained-unit-name">{unit.name}</span>
          <span className="contained-unit-type">{unit.type}</span>
        </div>
        
        {unit.description && (
          <div className="contained-unit-description">{unit.description}</div>
        )}
        
        <div className="contained-unit-details">
          {unit.uuaa && <span className="detail">UUAA: {unit.uuaa}</span>}
          {unit.code && <span className="detail">Code: {unit.code}</span>}
          {unit.className && <span className="detail">Class: {unit.className}</span>}
        </div>
      </div>
    );
  };

  // Main render
  if (!architectureData || !architectureData.deploymentUnits || architectureData.deploymentUnits.length === 0) {
    return (
      <div className="nested-renderer empty">
        <div className="empty-message">
          <h4>No Architecture Data</h4>
          <p>Create some deployment units to see the architecture visualization</p>
        </div>
      </div>
    );
  }

  const rootUnits = getRootUnits(architectureData.deploymentUnits);
  const allUnits = architectureData.deploymentUnits;

  return (
    <div className="nested-renderer">
      <div className="renderer-header">
        <h3>Architecture Hierarchy</h3>
        <div className="stats">
          <span>Total Units: {allUnits.length}</span>
          <span>Root Units: {rootUnits.length}</span>
        </div>
      </div>
      
      <div className="architecture-content">
        {rootUnits.map(unit => renderDeploymentUnit(unit, 0, allUnits))}
      </div>
    </div>
  );
};

export default NestedArchitectureRenderer;
